#!/usr/bin/env bash
# Freddy Fix It — apply-picks-view.sh
#
# SUPERSET installer. Carries everything from apply-payout-requirements.sh
# (plain-English Stripe payout steps) PLUS the new admin "who got picked" view.
# Run ONLY this one; running the older installer afterwards would revert this work.
set -e

cd ~/freddy-fixit || { echo "Could not find ~/freddy-fixit"; exit 1; }

echo "==> Clearing any stale git lock"
rm -f .git/index.lock

echo "==> Syncing with GitHub"
git fetch origin
git checkout main
git reset --hard origin/main

TMPB64="$(mktemp)"
trap 'rm -f "$TMPB64"' EXIT

# Reads a base64 heredoc into a temp file, then decodes it to $1.
# (macOS uses -D/-i/-o, GNU uses -d — try GNU first, fall back to BSD.)
wf() {
  mkdir -p "$(dirname "$1")"
  cat > "$TMPB64"
  base64 -d "$TMPB64" > "$1" 2>/dev/null || base64 -D -i "$TMPB64" -o "$1"
  echo "    wrote $1"
}

echo "==> Writing files"
wf "src/lib/stripeRequirements.ts" <<'FFB64_0'
