echo "==> Type checking"
npm run typecheck

echo "==> Building"
npx vite build

echo "==> Committing"
git add -A
git reset -q apply-picks-view.sh 2>/dev/null || true
git commit -m "Admin: show which contractor a client picked (winner on requests, names on jobs, new Picks tab) + plain-English Stripe payout steps"
git push origin main

echo ""
echo "✅ Changes pushed. Vercel is deploying now."
echo "   Wait ~1 minute, then hard-refresh your browser (Cmd+Shift+R)."
